export const POPULATION=120000000;
export function grade(s){const a=Math.floor(s.day/365),start={preschool:0,kindergarten:3,primary:6,middle:12,high:15,university:18,master:22,phd:25,preparation:15}[s.stage];if(start===undefined)return '';const n=Math.max(1,a-start+1),limit={preschool:3,kindergarten:3,primary:6,middle:3,high:3,university:4,master:3,phd:4,preparation:3}[s.stage];return `${Math.min(n,limit)}年级`;}
export function nationalStanding(s){if(s.stage==='work'&&s.progress>=1&&!s.retired&&!s.ended)return {rank:1,percent:100,label:'举国之首 · 国家主席'};const mean=s.stats.reduce((n,x)=>n+x,0)/5;let score=Math.min(.8,Math.max(0,(mean-5)/240));if(s.stage==='work')score=Math.max(score,.82+.179999*Math.min(1,s.progress));const rank=Math.max(2,Math.round(POPULATION*(1-score)**3));const percent=(1-(rank-1)/POPULATION)*100;return {rank,percent,label:percent>=99.99?'人中龙凤':percent>=99?'卓尔不群':percent>=90?'崭露头角':'平凡亦有光'};}
function rand(s){s.familyRng=(Math.imul(s.familyRng,1664525)+1013904223)>>>0;return s.familyRng/4294967296;}
export function familyYear(s,emit){const a=Math.floor(s.day/365);if(a<21)return;const pick=xs=>xs[Math.floor(rand(s)*xs.length)];const prior=s.maritalStatus;
if(s.maritalStatus!=='married'&&a<=55&&rand(s)<.14){const gender=s.gender==='男'?'女':'男',delta=Math.floor(rand(s)*9)-4;s.spouse={name:pick(['沈','陆','许','苏','周','江'])+pick(gender==='女'?['清禾','望舒','以宁','云岚']:['行舟','明川','书衡','景和']),gender,birthYear:Math.max(0,a-Math.max(21,a+delta)),ageAtMarriage:Math.max(21,a+delta),marriedAt:a,trait:pick(['温和体贴','勤勉务实','积极进取','自由浪漫']),occupation:pick(['教师','工程师','医生','研究员','经营者','文艺工作者'])};s.maritalStatus='married';emit('marriage',`${s.name}与${s.spouse.name}结为伴侣，对方是一位${s.spouse.trait}的${s.spouse.occupation}。`,true);}
else if(s.maritalStatus==='married'&&a>s.spouse.marriedAt){const spouseAge=s.spouse.ageAtMarriage+a-s.spouse.marriedAt;if(spouseAge>=65&&rand(s)<.025){s.maritalStatus='widowed';emit('family','伴侣因年老离世，往后的岁月带着共同的回忆前行。');}else if(a<65&&rand(s)<.008){s.maritalStatus='divorced';emit('family','经过慎重协商，你与伴侣选择分开生活，仍共同承担家庭责任。');}else if(a<=50&&spouseAge<=50&&s.children.length<3&&rand(s)<.17){const gender=pick(['男','女']),child={name:s.name.slice(0,1)+pick(['知夏','予安','星禾','景初','云舒','若川']),gender,bornAt:a};s.children.push(child);emit('birth',`${s.name}的家庭迎来第${s.children.length}个孩子：${child.name}，${gender==='男'?'男孩':'女孩'}。`,true);}}
if(s.maritalStatus==='married'){const trait=s.spouse.trait,base=trait==='勤勉务实'?.0009:trait==='积极进取'?.0012:trait==='温和体贴'?.0005:0;const change=base+(rand(s)-.5)*.004;s.familyMomentum=Math.max(-.018,Math.min(.025,s.familyMomentum+change));const text=change>=0?`${s.spouse.name}与你分担生活事务，你有更多精力投入学业或工作。`:`${s.spouse.name}的工作与家庭事务需要协调，你暂时调整了个人节奏。`;emit('family',text);}else{s.familyMomentum*=.9;}if(prior!==s.maritalStatus)s.familyHistory.push({age:a,status:s.maritalStatus,name:s.spouse?.name||''});}
export function familySummary(s){const labels={single:'未婚',married:'已婚',divorced:'离异',widowed:'丧偶'};return {status:labels[s.maritalStatus],spouse:s.spouse?`${s.spouse.name} · ${s.spouse.occupation} · ${s.spouse.trait}`:'缘分尚在途中',children:s.children.map(c=>({...c,age:Math.max(0,Math.floor(s.day/365)-c.bornAt)}))};}
export function avatar(s){const a=Math.floor(s.day/365),female=s.gender==='女',old=a>=60,middle=a>=40,child=a<18,baby=a<3;const hair=old?'#b9b8ad':middle?'#50504b':'#293d36',shirt=female?'#938674':'#537c70',bg=female?'#ece1d4':'#dce8dd',skin=['#eac7a4','#dfb88f','#f0d3b5'][s.avatarVariant||0];return `<svg viewBox="0 0 120 140" role="img" aria-label="${s.gender}性${baby?'婴幼儿':child?'少年':old?'老年':middle?'中年':'青年'}头像"><rect width="120" height="140" rx="16" fill="${bg}"/><circle cx="60" cy="56" r="${baby?34:child?30:28}" fill="${skin}"/>${female&&!baby?`<path d="M27 88V45C27 7 95 7 95 47V91L82 83V42C63 51 49 44 37 41V89Z" fill="${hair}"/>`:`<path d="M29 46C22 9 97 6 91 46L80 36 58 32 35 43Z" fill="${hair}"/>`}<path d="M18 140V117Q23 91 49 90L60 101 71 90Q100 94 104 117V140" fill="${shirt}"/><path d="M48 87L60 101 72 87" fill="${skin}"/><circle cx="49" cy="57" r="2.5" fill="#33433b"/><circle cx="72" cy="57" r="2.5" fill="#33433b"/><path d="M52 73Q60 79 69 72" fill="none" stroke="#9e6757" stroke-width="2" stroke-linecap="round"/>${old?'<path d="M40 63L47 65M74 65L81 62M48 79L45 83M73 79L76 83M48 49L54 48M67 48L74 49" stroke="#b58e72" fill="none"/>':''}${middle?'<g stroke="#637068" fill="none"><rect x="40" y="51" width="18" height="13" rx="5"/><rect x="64" y="51" width="18" height="13" rx="5"/><path d="M58 56H64"/></g>':''}${baby?'<ellipse cx="40" cy="69" rx="6" ry="3" fill="#e5a992" opacity=".6"/><ellipse cx="81" cy="69" rx="6" ry="3" fill="#e5a992" opacity=".6"/>':''}</svg>`;}

